// ===================== NPC LIBRARY DATA =====================
// Backing data for the NPCs tab (see renderNpcsTab in the main file). Split into its own file
// the same way loot-data.js/cult-data.js/trap-data.js are — pure content, no logic, loaded via a
// plain <script src> before the main file's own script runs.
//
// Original content written for this project. Set in the Ashcrown Empire — a tyrannical state
// ruled from the capital, Karvossa, by House Draventh — and its opposition, a rebellion called
// the Broken Crown. Three factions: Empire (the court and its instruments), Neutral (ordinary
// people in Ashcrown territory who aren't aligned with either side), and Rebel (the Broken
// Crown and its allies). Several entries tie directly into CULT_LIBRARY (see cult-data.js) —
// the Ashbond, the Queen's Legion, and the Black Books all now operate partly or wholly
// through the Ashcrown court -- and, beneath all three, a quiet cabal of Karvossa's wealthiest
// merchant-lords and old nobility, who use the Black Books' leverage and a pair of trusted
// hands at court to keep the throne itself more manageable than anyone outside the palace
// realizes. See empress-isolde's own secrets field for the specifics.
//
// One shape:
//   {
//     id: "unique-slug",
//     name, title, faction: "Empire"|"Neutral"|"Rebel", role,
//     alignment, ac, hp (in the same "N (XdY+Z)" format monster records use), speed,
//     attacks: [{ name, text }],
//     weapon: "name of a signature weapon — see NPC_WEAPONS below, or freeform if not in it",
//     backstory: "who they are and how they got here",
//     secrets: "DM-facing hidden information — not something the NPC volunteers",
//     cultTie: "a CULT_LIBRARY entry name this NPC is connected to, or null",
//     location: "where a party would actually find them",
//   }
// DM edits to any of these fields are stored separately (see npcEdits in the main file) and
// overlaid at render time, so this file itself never needs to be hand-edited to reflect a
// live campaign's changes.

const NPC_WEAPONS = [
  { name: "Cinderfall", desc: "The Lord Commander's greatsword, forged from meteoric iron and quenched in dragon's blood during the Ashcrown's conquest of the Cinder Coast. The blade never quite cools — Bastian Reave can light a torch off the edge in cold weather, and has, more than once, just to unsettle whoever he's meeting with.", type: "weapon", slotSize: 2, gp: "—", dmg: "2d6+5", effect: "+2 attack and damage. Once per turn on a hit, deal an extra 2d6 fire damage. Requires attunement by a creature of Lawful alignment." },
  { name: "The Vayle Codex", desc: "Not a book — a wand disguised as one, its spine bound in what the Archmagus insists is ordinary leather. Selwyn Vayle has carried it since his apprenticeship, and it's absorbed enough of his own spellwork over the decades that it now argues back, in a small dry voice only he claims to hear.", type: "weapon", slotSize: 1, gp: "—", dmg: "1d4", effect: "+3 to spell attack rolls and spell save DC while wielded. Once per long rest, cast Counterspell without using a spell slot or reaction — it happens automatically, faster than thought, whether or not its owner wanted it to." },
  { name: "Korrin's Reckoning", desc: "General Thessaly Korrin's warhammer, cast from the melted-down chains of a rebellion she put down twenty years ago in the Cinder Coast — a trophy she commissioned herself, and wears without a trace of irony.", type: "weapon", slotSize: 2, gp: "—", dmg: "2d6+4", effect: "+2 attack and damage. On a critical hit, the target is Stunned until the end of its next turn." },
  { name: "Ashwick's Needle", desc: "A slim, unremarkable dagger the Imperial spymaster carries openly, on the theory that a weapon nobody bothers hiding is never suspected of anything.", type: "weapon", slotSize: 1, gp: "—", dmg: "1d4", effect: "Finesse, light, thrown (range 20/60). +1d6 poison damage on a hit against a creature that hasn't acted yet this combat." },
  { name: "The Faircross Seal", desc: "Not a weapon by trade — a magistrate's signet ring, heavy gold, that Odessa Faircross has worn since her founding of the Queen's Legion. Every ruling she's ever quietly redirected carries its impression.", type: "misc", subcategory: "ring", slotSize: 1, gp: "—", effect: "While worn: once per long rest, force one creature within 30 ft. to make a DC 16 Wisdom save or be compelled to answer your next direct question honestly. Requires attunement." },
  { name: "Vane's Judgment", desc: "The Grand Inquisitor's mace, blessed by a rite the Ashcrown temple no longer performs openly — it was meant, once, to be used against genuine heresy. Darrow Vane has widened the definition considerably.", type: "weapon", slotSize: 1, gp: "—", dmg: "1d6+4", effect: "+2 attack and damage. +2d6 radiant damage against a creature that has lied to you in the last minute." },
  { name: "Thorne's Answer", desc: "Commander Elara Thorne's longsword — Imperial-forged, taken off a Lord Commander's second-in-command the night she deserted. She's never had it reforged or rehilted. She wants every rebel who sees it to know exactly where it came from.", type: "weapon", slotSize: 1, gp: "—", dmg: "1d8+4", effect: "+2 attack and damage. Once per short rest, when you hit a creature wearing Ashcrown colors, gain advantage on your next attack roll against a different Ashcrown target within 1 minute." },
  { name: "The Cinderwright's Press", desc: "A collapsible printing frame small enough to fit in a courier's pack, used to run off pamphlets by moonlight and vanish before dawn. Not a weapon in any conventional sense — the Broken Crown considers it one of their most dangerous assets anyway.", type: "misc", subcategory: "commonMisc", slotSize: 1, gp: "—", effect: "A single sheet run from this press, distributed and read aloud in a town within Ashcrown territory, grants the reader advantage on the next Charisma (Persuasion) check made to recruit help from the local population, once per settlement per month." },
];

